SOURCES['wave.glsl'] = '// Shared analytic effects. Coordinates and widths are logical pixels.\nfloat shadow_shape_distance(vec2 p, vec2 size, vec4 radii) {\n    float radius = p.y < size.y * .5 ?\n        (p.x < size.x * .5 ? radii.x : radii.y) :\n        (p.x < size.x * .5 ? radii.w : radii.z);\n    radius = clamp(radius, 0.0, min(size.x, size.y) * .5);\n    vec2 q = abs(p - size * .5) - size * .5 + radius;\n    return min(max(q.x, q.y), 0.0) + length(max(q, 0.0)) - radius;\n}\n\nfloat gaussian_shadow(float distance, float sigma) {\n    // Normal cumulative distribution, approximated without a blur texture.\n    float x = abs(distance) / max(sigma, .001);\n    float t = 1.0 / (1.0 + .2316419 * x);\n    float tail = .39894228 * exp(-.5*x*x) * t *\n        (.31938153 + t * (-.35656378 + t *\n         (1.78147794 + t * (-1.82125598 + t * 1.33027443))));\n    return distance >= 0.0 ? tail : 1.0-tail;\n}\n\nfloat elevation_shadow(vec2 p, vec2 size, vec4 radii, vec4 info) {\n    p -= vec2(info.w);\n    size -= vec2(info.w * 2.0);\n    float ambient = gaussian_shadow(shadow_shape_distance(p, size, radii), info.x) * (28.0/255.0);\n    float key = gaussian_shadow(shadow_shape_distance(p-vec2(0,info.z), size, radii), info.y) * (40.0/255.0);\n    return key + ambient * (1.0-key);\n}\n\nfloat wave_line_distance(vec2 p, vec4 wave, vec4 info) {\n    float a = wave.x;\n    float b = wave.y;\n    float amplitude = wave.z;\n    float wavelength = max(wave.w, 0.001);\n    float x = clamp(p.x, a, b);\n    float taper = clamp(min((x-a), (b-x)) / (wavelength * .25), 0.0, 1.0);\n    float angle = x / wavelength * 6.28318530718 - info.x;\n    float y = info.z + amplitude * taper * sin(angle);\n    float taper_slope = taper < 1.0 ? (x-a < b-x ? 4.0 : -4.0) / wavelength : 0.0;\n    float slope = amplitude * (taper_slope * sin(angle) +\n                              taper * cos(angle) * 6.28318530718 / wavelength);\n    // Project onto the local tangent. Endpoints keep circular stroke caps.\n    float d = p.x < a || p.x > b ? length(p - vec2(x, y)) :\n              abs(p.y-y) / sqrt(1.0+slope*slope);\n    return d - info.y * .5;\n}\n\nfloat wave_arc_distance(vec2 p, vec4 wave, vec4 info) {\n    float radius = wave.x;\n    float start = wave.y;\n    float sweep = clamp(wave.z, 0.0, 6.28318530718);\n    float amplitude = wave.w;\n    float theta = atan(p.y, p.x);\n    float relative = mod(theta - start, 6.28318530718);\n    float angle = start + relative;\n    float r = radius + amplitude * sin(angle * info.z - info.x);\n    float derivative = amplitude * info.z * cos(angle * info.z - info.x);\n    float d = abs(length(p)-r) / sqrt(1.0+derivative*derivative / max(r*r, .001));\n    if (relative > sweep && sweep < 6.283184) {\n        vec2 first = vec2(cos(start), sin(start)) *\n                     (radius+amplitude*sin(start*info.z-info.x));\n        float end = start+sweep;\n        vec2 last = vec2(cos(end), sin(end)) *\n                    (radius+amplitude*sin(end*info.z-info.x));\n        d = min(length(p-first), length(p-last));\n    }\n    return d - info.y * .5;\n}\n'

SOURCES['effects.glsl'] = '// Portable procedural fragments shared by OpenGL and Vulkan. Coordinates are\n// normalized inside the control; all colors use straight alpha.\nfloat effect_hash(vec2 p) {\n    p = fract(p * vec2(123.34, 456.21));\n    p += dot(p, p + 45.32);\n    return fract(p.x * p.y);\n}\n\nfloat effect_noise(vec2 p) {\n    vec2 cell = floor(p), f = fract(p);\n    f = f * f * (3.0 - 2.0 * f);\n    return mix(mix(effect_hash(cell), effect_hash(cell + vec2(1.0, 0.0)), f.x),\n               mix(effect_hash(cell + vec2(0.0, 1.0)),\n                   effect_hash(cell + vec2(1.0, 1.0)), f.x), f.y);\n}\n\nvec4 procedural_effect(vec2 uv, vec2 size, float mode, vec4 first,\n                       vec4 second, vec4 parameters, vec4 information) {\n    float elapsed = parameters.x;\n    float strength = clamp(parameters.y, 0.0, 1.0);\n    float frequency = max(parameters.z, 0.001);\n    vec2 center = information.xy;\n    float angle = information.z;\n    vec2 p = uv - center;\n    // Preserve circular rings when the control is not square.\n    vec2 aspect = size / max(min(size.x, size.y), 0.001);\n    float baseline = clamp(dot(p, vec2(cos(angle), sin(angle))) + 0.5, 0.0, 1.0);\n    float value;\n    if (mode < 0.5) {\n        float animated_angle = angle + elapsed * 0.25;\n        value = clamp(dot(p, vec2(cos(animated_angle), sin(animated_angle))) +\n                      0.5, 0.0, 1.0);\n    } else if (mode < 1.5) {\n        vec2 sample_pos = uv * aspect * frequency + vec2(elapsed * .18, elapsed * .11);\n        value = .57 * effect_noise(sample_pos) +\n                .28 * effect_noise(sample_pos * 2.03) +\n                .15 * effect_noise(sample_pos * 4.07);\n    } else if (mode < 2.5) {\n        float phase = length(p * aspect) * frequency * 6.28318530718 - elapsed * 2.0;\n        // Fade frequencies above the fragment Nyquist limit instead of aliasing.\n        float attenuation = 1.0 - smoothstep(1.2, 3.14159265359, fwidth(phase));\n        value = 0.5 + 0.5 * sin(phase) * attenuation;\n    } else {\n        vec2 q = p * aspect * frequency;\n        value = .5 + (sin(q.x + elapsed) + sin(q.y - elapsed * .7) +\n                      sin((q.x + q.y) * .7 + elapsed * .4)) / 6.0;\n    }\n    value = mix(baseline, clamp(value, 0.0, 1.0), strength);\n    // Interpolate premultiplied colors, then convert back for normal blending.\n    float alpha = mix(first.a, second.a, value);\n    vec3 rgb = mix(first.rgb * first.a, second.rgb * second.a, value) /\n               max(alpha, 0.00001);\n    float radius = clamp(parameters.w, 0.0, min(size.x, size.y) * .5);\n    vec2 local = (uv - .5) * size;\n    vec2 q = abs(local) - (size * .5 - radius);\n    float distance = length(max(q, 0.0)) + min(max(q.x, q.y), 0.0) - radius;\n    float feather = max(.65 * fwidth(distance), .001);\n    float coverage = 1.0 - smoothstep(-feather, feather, distance);\n    return vec4(rgb, alpha * coverage);\n}\n'
